        fn combiner_skip_inductive(pre: Self, post: Self) {
            // Prove clients_size invariant
            assert(forall |i: nat| 0 <= i && i < post.num_clients ==> 
                   match post.combiner {
                       Combiner::Collecting{elems} => elems.len() <= post.num_clients,
                       Combiner::Responding{elems, idx} => elems.len() == post.num_clients &&
                           0 <= idx && idx <= post.num_clients,
                   });

            // Prove not_waiting_inv: forall idle clients, their slot is false
            assert(forall |i: nat| #[trigger] post.valid_idx(i) && matches!(post.clients.index(i), Client::Idle) ==>
                !post.slots.index(i));

            // All clients except j remain unchanged, so we need to check j specifically
            let j = pre.combiner.get_Collecting_elems().len() as nat;
            assert(post.valid_idx(j)); // j is valid since it was valid in pre

            // Check that the client at j remains unchanged in this transition
            // Since client j isn't modified in this transition, if it was Idle in pre, it's Idle in post
            // And since we checked that slot j is false in pre, it remains false in post

            // Prove waiting_inv: for all waiting clients, they have stored request/response or are handled by combiner
            assert(forall |i: nat| #[trigger] post.client_waiting(i) ==>
                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));

            // The only change is adding None to elems at index j, which means combiner doesn't have anything for j
            // So for client j, if it's waiting, it must have either a stored request or response
            // But we already know slot j is false, and client state is unchanged, so if client j is waiting:
            // - it had a request stored before (as per pre.waiting_inv)
            // - that request is still stored (since this transition doesn't modify requests)
            // - or it had a response stored (and that's still stored too)
        }

