    && match self.combiner {
        Combiner::Collecting{elems} => i < elems.len() && matches!(elems.index(i as int), Option::Some(_)),
        Combiner::Responding{elems, idx} => i >= idx && matches!(elems.index(i as int), Option::Some(_)),
    }
}

