#[inductive(combiner_skip)]
fn combiner_skip_inductive(pre: Self, post: Self) {
    // j is the index of the element that gets added as None to the collecting elems
    let j = pre.combiner.get_Collecting_elems().len();

    // Prove clients_size invariant
    match post.combiner {
        Combiner::Collecting{elems} => {
            assert(elems.len() == pre.combiner.get_Collecting_elems().len() + 1);
            assert(pre.combiner.get_Collecting_elems().len() < pre.num_clients);
            assert(elems.len() <= post.num_clients);
        },
        _ => {}
    }

    // Prove not_waiting_inv: for all idle clients, their slots must be false
    assert(forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() ==> 
        !post.slots.index(i)) by {
        // The transition keeps all client states and slots unchanged
        // and the only constraint is that slot j is false (enforced by "have slots >= [j => false]")
        // The invariant holds by preservation from pre state
        assert(pre.valid_idx(i) && pre.clients.index(i).is_Idle() ==> !pre.slots.index(i));
    };

    // Prove waiting_inv: for all waiting clients, they must have a stored request, response, or be handled by combiner
    assert(forall |i: nat| #[trigger] post.client_waiting(i) ==> 
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)) by {
        if i == j {
            // Special case for the client at index j which we're skipping
            if post.client_waiting(i) {
                // pre.client_waiting(i) also holds since client state unchanged
                // By pre's waiting_inv, we know pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i)
                // But post.combiner_has(i) is false because we added Option::None at index i
                // And we know slot i is false (by the "have" clause)
                // Thus client i must have a request or response stored
                assert(post.request_stored(i) || post.response_stored(i));
            }
        } else {
            // For all other indices, everything is preserved from pre state
            assert(post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
        }
    };
}

