#[inductive(combiner_skip)]
fn combiner_skip_inductive(pre: Self, post: Self) {
    // Get the index of the element that gets added to the collecting elems
    let j = pre.combiner.get_Collecting_elems().len();

    // Verify that j is still a valid index  
    assert(j < pre.num_clients);

    // Prove size invariant: post.combiner is Collecting with one more element
    match post.combiner {
        Combiner::Collecting{elems} => {
            assert(elems.len() == pre.combiner.get_Collecting_elems().len() + 1);
            assert(elems.len() <= post.num_clients);
        }
        _ => {}
    }

    // Prove not_waiting_inv: For any idle client, its slot is false
    // Since the transition doesn't change any client states or slots (except enforcing slot j is false),
    // and pre satisfied the invariant, post satisfies it too.
    assert(forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() ==> 
           !post.slots.index(i));

    // Prove waiting_inv: Any waiting client has a request, response, or is handled by combiner
    // Case 1: client j (the one we're skipping)
    if post.client_waiting(j) {
        // pre.client_waiting(j) also holds
        // From pre's invariant, pre.client_waiting(j) ==> pre.request_stored(j) || pre.response_stored(j) || pre.combiner_has(j)

        // In post: 
        // - post.combiner_has(j) is false (because we added None at position j)
        // - post.slots.index(j) is false (enforced by "have slots >= [j => false]")
        // - client state is unchanged
        // Therefore, post.request_stored(j) || post.response_stored(j) must hold
        assert(post.request_stored(j) || post.response_stored(j));
    }

    // Case 2: all other clients k != j have unchanged state
    assert(forall |k: nat| k != j && #[trigger] post.client_waiting(k) ==> 
           post.request_stored(k) || post.response_stored(k) || post.combiner_has(k));
}

